def ece(confidences, correct, n_bins=10):
    bins = {}
    for c, ok in zip(confidences, correct):
        b = min(int(c * n_bins), n_bins - 1)
        bins.setdefault(b, []).append((c, 1 if ok else 0))
    n = len(confidences)
    total = 0.0
    for items in bins.values():
        size = len(items)
        acc = sum(ok for _, ok in items) / size
        conf = sum(c for c, _ in items) / size
        total += size / n * abs(acc - conf)
    return total
